// GENERATED by tools/build-quests.ps1 from the tag:<tag>*N tasks in tools/content. Do not edit by hand.
// An item task only accepts one item id. For materials that several mods make (steel, osmium, titanium, ...)
// the quest uses a stage task instead, and this script gives the stage when the inventory holds N of the tag.

const GSPACK_TAG_STAGES = [
  ['gspack_tag_gspack_home_storage_2', '#gspack:home_storage', 2],
  ['gspack_tag_minecraft_wooden_doors_1', '#minecraft:wooden_doors', 1],
  ['gspack_tag_c_ingots_osmium_1', '#c:ingots/osmium', 1],
  ['gspack_tag_c_ingots_steel_1', '#c:ingots/steel', 1],
  ['gspack_tag_c_silicon_1', '#c:silicon', 1],
  ['gspack_tag_c_raw_materials_nickel_8', '#c:raw_materials/nickel', 8],
  ['gspack_tag_c_ingots_nickel_8', '#c:ingots/nickel', 8],
  ['gspack_tag_c_raw_materials_platinum_4', '#c:raw_materials/platinum', 4],
  ['gspack_tag_c_ingots_electrum_8', '#c:ingots/electrum', 8],
  ['gspack_tag_c_ingots_brass_8', '#c:ingots/brass', 8],
  ['gspack_tag_c_ingots_knightmetal_8', '#c:ingots/knightmetal', 8],
  ['gspack_tag_c_raw_materials_titanium_8', '#c:raw_materials/titanium', 8],
  ['gspack_tag_c_ingots_titanium_1', '#c:ingots/titanium', 1],
  ['gspack_tag_c_ingots_titanium_8', '#c:ingots/titanium', 8],
  ['gspack_tag_c_ingots_silver_4', '#c:ingots/silver', 4],
  ['gspack_tag_c_gems_fluorite_4', '#c:gems/fluorite', 4],
]

PlayerEvents.inventoryChanged(event => {
  const player = event.player
  GSPACK_TAG_STAGES.forEach(([stage, tag, count]) => {
    if (!player.stages.has(stage) && player.inventory.count(tag) >= count) player.stages.add(stage)
  })
})
